#include "pattern_fixed_stage.h"
#include <stdint.h>
#include <string.h>
static int overlap(const void *a,size_t n,const void *b,size_t m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return n&&m&&(x<=y?y-x<n:x-y<m);}
static int layout_safe(fm1_fixed_stage *s){const void *p[12];size_t n[12];unsigned i,j;fm1_project_work *w=s->work;if(!w)return 0;p[0]=s;n[0]=sizeof *s;p[1]=s->store;n[1]=s->store?sizeof *s->store:0;p[2]=w;n[2]=sizeof *w;p[3]=w->pattern;n[3]=w->pattern?sizeof *w->pattern:0;p[4]=w->session;n[4]=w->session?FM1_PROJECT_SESSION:0;p[5]=w->arena;n[5]=w->arena_capacity;p[6]=w->compressed;n[6]=w->compressed_capacity;p[7]=s->session;n[7]=FM1_PROJECT_SESSION;p[8]=s->bank;n[8]=s->bank?sizeof *s->bank:0;p[9]=s->arena;n[9]=s->capacity;p[10]=s->live;n[10]=s->live?sizeof *s->live:0;p[11]=s->state;n[11]=s->state?sizeof *s->state:0;if((n[5]&&!p[5])||(n[6]&&!p[6]))return 0;for(i=0;i<12;i++)for(j=0;j<i;j++)if(overlap(p[i],n[i],p[j],n[j])&&!((i==7&&j==4&&p[i]==p[j])||(i==9&&j==5&&p[i]==p[j]&&n[i]<=n[j])||(i==10&&j==3&&p[i]==p[j])))return 0;return 1;}
int fm1_fixed_stage_ready(fm1_fixed_stage *s){return s&&s->valid&&s->work&&s->work->pattern&&s->work->session&&s->session&&s->bank&&s->arena&&s->capacity&&s->live&&s->state&&s->safe&&s->faulted&&layout_safe(s)&&s->safe(s->guard_ctx)==1&&s->faulted(s->guard_ctx)==0;}
static int fail(fm1_fixed_stage *s){return s&&s->faulted&&s->faulted(s->guard_ctx)!=0?-1:0;}
int fm1_fixed_stage_source_separate(fm1_fixed_stage *s,const void *p,size_t n){fm1_project_work *w;if(!s||!s->work||(!p&&n))return 0;w=s->work;return !overlap(p,n,s,sizeof *s)&&!overlap(p,n,w,sizeof *w)&&!overlap(p,n,w->pattern,sizeof *w->pattern)&&!overlap(p,n,w->session,FM1_PROJECT_SESSION)&&!overlap(p,n,w->arena,w->arena_capacity)&&!overlap(p,n,w->compressed,w->compressed_capacity)&&!overlap(p,n,s->session,FM1_PROJECT_SESSION)&&!overlap(p,n,s->bank,sizeof *s->bank)&&!overlap(p,n,s->arena,s->capacity)&&!overlap(p,n,s->live,sizeof *s->live)&&!overlap(p,n,s->state,sizeof *s->state);}
int fm1_fixed_stage_preflight(void *v,const uint8_t *p,size_t n){fm1_fixed_stage *s=v;int rc;if(!p||!fm1_fixed_stage_ready(s)||!fm1_fixed_stage_source_separate(s,p,n))return 0;rc=fm1_compressed_project_decode(p,n,s->valid,s->validate_ctx,s->work,s->session,s->bank,s->arena,s->capacity,s->live,s->state);return rc==FM1_PROJECT_OK&&s->safe(s->guard_ctx)==1&&s->faulted(s->guard_ctx)==0;}
static int stage(fm1_fixed_stage *s,uint32_t slot,pops_certify_fn cert,void *certctx,ps_info *info){int rc;if(!fm1_fixed_stage_ready(s)||!s->store||!s->payload||!cert)return fail(s);rc=fm1_fixed_project_load_info(s->store,slot,s->payload,cert,certctx,s->valid,s->validate_ctx,s->work,s->session,s->bank,s->arena,s->capacity,s->live,s->state,info);if(rc!=PS_OK||s->safe(s->guard_ctx)!=1||s->faulted(s->guard_ctx)!=0)return fail(s);return 1;}
int fm1_fixed_stage_load(void *v,uint32_t slot,pops_certify_fn cert,void *certctx){ps_info info;return stage(v,slot,cert,certctx,&info);}
int fm1_fixed_stage_working(void *v,pops_certify_fn cert,void *certctx,char name[PS_NAME_BYTES]){fm1_fixed_stage *s=v;ps_info info;int rc;if(!name||!s||overlap(name,PS_NAME_BYTES,s,sizeof *s)||overlap(name,PS_NAME_BYTES,s->payload,FM1_FIXED_PAYLOAD)||overlap(name,PS_NAME_BYTES,s->store,s->store?sizeof *s->store:0)||overlap(name,PS_NAME_BYTES,s->work,s->work?sizeof *s->work:0)||(s->work&&(overlap(name,PS_NAME_BYTES,s->work->pattern,s->work->pattern?sizeof *s->work->pattern:0)||overlap(name,PS_NAME_BYTES,s->work->session,s->work->session?FM1_PROJECT_SESSION:0)||overlap(name,PS_NAME_BYTES,s->work->arena,s->work->arena_capacity)||overlap(name,PS_NAME_BYTES,s->work->compressed,s->work->compressed_capacity)))||overlap(name,PS_NAME_BYTES,s->session,FM1_PROJECT_SESSION)||overlap(name,PS_NAME_BYTES,s->bank,s->bank?sizeof *s->bank:0)||overlap(name,PS_NAME_BYTES,s->arena,s->capacity)||overlap(name,PS_NAME_BYTES,s->live,s->live?sizeof *s->live:0)||overlap(name,PS_NAME_BYTES,s->state,s->state?sizeof *s->state:0))return 0;rc=stage(s,FM1_FIXED_WORKING_SLOT,cert,certctx,&info);if(rc==1)memcpy(name,info.name,PS_NAME_BYTES);return rc;}
